CREATE FUNCTION public.ict_directory() RETURNS TABLE(id uuid,full_name text,office_id uuid,section_id uuid,user_id uuid,is_technician boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT o.id,o.full_name,o.office_id,o.section_id,o.user_id,EXISTS(SELECT 1 FROM user_roles ur WHERE ur.user_id=o.user_id AND ur.role IN ('ict_admin','system_admin')) FROM officers o WHERE auth.uid() IS NOT NULL $$;
REVOKE ALL ON FUNCTION public.ict_directory() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.ict_directory() TO authenticated;
CREATE FUNCTION public.ict_supervisor(_officer uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.hr_head(_officer) OR EXISTS(SELECT 1 FROM officers o JOIN officers s ON s.id=o.supervisor_id WHERE o.id=_officer AND s.user_id=auth.uid()) $$;
CREATE POLICY ict_supervisor_read ON public.ict_records FOR SELECT TO authenticated USING(kind='requests' AND public.ict_supervisor(officer_id));
CREATE OR REPLACE FUNCTION public.ict_file_access(_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM ict_records r WHERE r.attachments @> jsonb_build_array(jsonb_build_object('path',_path)) AND (ict_staff() OR r.created_by=auth.uid() OR (r.kind='requests' AND ict_supervisor(r.officer_id)) OR (r.kind='knowledge' AND r.status='Published') OR (r.kind<>'accounts' AND has_any_role(auth.uid(),ARRAY['commandant']::app_role[])))) $$;